"use client";

/**
 * Offline + install: registers the service worker (production builds only; it's generated by
 * scripts/build-sw.mjs), keeps the browser's install prompt for later, and <OfflineHint> tells the
 * player whether the game is saved for offline play and how to install it.
 */
import { useEffect, useState } from "react";

type InstallEvent = Event & { prompt(): Promise<void>; userChoice: Promise<{ outcome: string }> };
const w = () => window as unknown as { __nfInstall?: InstallEvent | null };

export function SwRegister() {
  useEffect(() => {
    const keep = (e: Event) => {
      e.preventDefault();
      w().__nfInstall = e as InstallEvent;
      window.dispatchEvent(new Event("nf:install"));
    };
    window.addEventListener("beforeinstallprompt", keep);
    const params = new URLSearchParams(window.location.search);
    if (process.env.NODE_ENV === "production" && "serviceWorker" in navigator && params.get("sw") !== "0") {
      navigator.serviceWorker.register("/sw.js", { scope: "/" }).catch((e) => console.warn("service worker:", e));
    }
    return () => window.removeEventListener("beforeinstallprompt", keep);
  }, []);
  return null;
}

/** "Works offline ✓" once the service worker holds the game, plus Install (Android / desktop Chrome) or the iPhone steps */
export function OfflineHint({ compact = false }: { compact?: boolean }) {
  const [ready, setReady] = useState(false);
  const [canInstall, setCanInstall] = useState(false);
  const [ios, setIos] = useState(false);
  const [installed, setInstalled] = useState(false);
  useEffect(() => {
    const standalone = window.matchMedia?.("(display-mode: standalone)").matches || (navigator as unknown as { standalone?: boolean }).standalone === true;
    setInstalled(!!standalone);
    setIos(/iP(hone|ad|od)/.test(navigator.userAgent) || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1));
    setCanInstall(!!w().__nfInstall);
    const onInstall = () => setCanInstall(!!w().__nfInstall);
    window.addEventListener("nf:install", onInstall);
    const onInstalled = () => {
      setInstalled(true);
      setCanInstall(false);
    };
    window.addEventListener("appinstalled", onInstalled);
    let alive = true;
    // "ready" = an active worker, which only activates after the whole game is cached
    navigator.serviceWorker?.ready.then(() => alive && setReady(true)).catch(() => {});
    return () => {
      alive = false;
      window.removeEventListener("nf:install", onInstall);
      window.removeEventListener("appinstalled", onInstalled);
    };
  }, []);
  const install = async () => {
    const ev = w().__nfInstall;
    if (!ev) return;
    w().__nfInstall = null;
    setCanInstall(false);
    await ev.prompt().catch(() => {});
  };
  return (
    <p className={`offline-hint${compact ? " compact" : ""}`} data-testid="offline-hint" data-ready={ready ? "true" : "false"}>
      <span className="offline-state">{ready ? "✓ Works offline: the game is saved on this device." : "Open once with internet and the game works offline."}</span>
      {!installed && canInstall && (
        <button type="button" className="install-btn" data-testid="install-app" onClick={install}>
          Install app
        </button>
      )}
      {!installed && !canInstall && ios && <span className="install-ios"> Install: tap Share, then “Add to Home Screen”.</span>}
      {!installed && !canInstall && !ios && !compact && <span className="install-other"> Install it from the browser menu to open it like an app.</span>}
    </p>
  );
}
